"@import url('https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700;800&family=Space+Grotesk:wght@500;700&display=swap');

:root {
    --bg-color: #f1f5fb;
    --sidebar-bg: #ffffff;
    --card-bg: rgba(255, 255, 255, 0.9);
    --primary: #06b6d4; /* Cyan/Teal */
    --primary-light: #cffafe;
    --secondary: #8b5cf6; /* Violet */
    --secondary-light: #ede9fe;
    --accent: #f43f5e; /* Rose */
    --text-main: #0f172a;
    --text-muted: #64748b;
}

body {
    font-family: 'Outfit', sans-serif;
    background-color: var(--bg-color);
    background-image: 
        radial-gradient(circle at 10% 20%, rgba(6, 182, 212, 0.08) 0%, transparent 40%),
        radial-gradient(circle at 90% 80%, rgba(139, 92, 246, 0.08) 0%, transparent 40%);
    background-attachment: fixed;
    color: var(--text-main);
    overflow-x: hidden;
}

/* Typography for Game-like numbers */
.font-display {
    font-family: 'Space Grotesk', sans-serif;
}

/* Anime/Gaming Card Style */
.game-card {
    background: var(--card-bg);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border: 2px solid rgba(255, 255, 255, 1);
    box-shadow: 0 10px 30px -10px rgba(15, 23, 42, 0.08), 
                inset 0 0 0 1px rgba(255, 255, 255, 0.5);
    border-radius: 28px;
    transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.3s ease;
}

.game-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 20px 40px -15px rgba(15, 23, 42, 0.12), 
                inset 0 0 0 1px rgba(255, 255, 255, 0.8);
}

/* Sidebar Specifics */
.sidebar {
    background: var(--sidebar-bg);
    box-shadow: 10px 0 30px -10px rgba(0,0,0,0.05);
    border-right: 1px solid rgba(226, 232, 240, 0.8);
}

.nav-item {
    transition: all 0.2s ease;
    color: var(--text-muted);
}

.nav-item.active {
    background: linear-gradient(135deg, var(--primary), #3b82f6);
    color: white;
    box-shadow: 0 8px 20px -6px rgba(6, 182, 212, 0.5);
}

